SourceCode.Declaration:
/// <summary>
/// Counting variance tolerance, one row per company (none = defaults, see find). Edited on
/// the Mobile count tolerance form (Setup). A line within
/// tolerance is MINOR_VARIANCE and needs no approval; outside it is RECOUNT_REQUIRED.
/// </summary>
public class HSMobileOpsCountTolerance extends common
{
}

Method.Source:
/// <summary>
/// This company's tolerance. With no row yet, the defaults (2 % or 0 units) are returned
/// without being written.
/// </summary>
public static HSMobileOpsCountTolerance find()
{
    HSMobileOpsCountTolerance tolerance;

    select firstOnly tolerance;
    if (!tolerance.RecId)
    {
        tolerance.TolerancePct = 2;
        tolerance.ToleranceQty = 0;
    }
    return tolerance;
}

/// <summary>
/// True when the variance is within either limit: at most ToleranceQty units, or at most
/// TolerancePct percent of the system quantity.
/// </summary>
public boolean withinTolerance(real _varianceQty, real _systemQty)
{
    real variance = abs(_varianceQty);

    if (variance <= this.ToleranceQty)
    {
        return true;
    }
    return _systemQty != 0 && (variance / abs(_systemQty)) * 100 <= this.TolerancePct;
}

public str describe()
{
    return strFmt('Within %1 % or %2 units', this.TolerancePct, this.ToleranceQty);
}

/// <summary>
/// The same defaults find() reports, so the row the setup form creates starts at 2 %
/// rather than zero (which would send every variance for approval).
/// </summary>
public void initValue()
{
    super();
    this.TolerancePct = 2;
    this.ToleranceQty = 0;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (this.TolerancePct < 0 || this.ToleranceQty < 0)
    {
        ret = checkFailed("Tolerance can't be negative.");
    }
    if (this.TolerancePct > 100)
    {
        ret = checkFailed("Tolerance % can't be more than 100.");
    }
    return ret;
}
